<?php $page_title='Users'; include 'includes/header.php'; $users=$pdo->query("SELECT id,name,email,phone,created_at FROM users WHERE role='customer' ORDER BY created_at DESC")->fetchAll(); ?><section class="page-banner"><div class="container"><div class="eyebrow">Registered customers</div><h1>Users</h1></div></section><section class="section"><div class="container"><table class="cart-table"><thead><tr><th>ID</th><th>Name</th><th>Email</th><th>Phone</th><th>Registered</th></tr></thead><tbody><?php foreach($users as $user): ?><tr><td data-label="ID"><?=$user['id']?></td><td data-label="Name"><?=esc($user['name'])?></td><td data-label="Email"><?=esc($user['email'])?></td><td data-label="Phone"><?=esc($user['phone'])?></td><td data-label="Registered"><?=date('d M Y',strtotime($user['created_at']))?></td></tr><?php endforeach; ?></tbody></table></div></section><?php include 'includes/footer.php'; ?>